           ERR( "mmap failed: %s(%d)", strerror( errno ), errno );
           return 0;
        }
        if ( mem_op == WRITE_MEM )
        {
           memcpy( mapAddr + memOffset, buf, numBytes );
        }
        else
        {
           memcpy( buf, mapAddr + memOffset, numBytes );
        }

        munmap( mapAddr, mapSize );
    }
