   const char *prop_name, *override_end;
   int len, override_len, name_len, target_len, phandle;
   const char *offset_seps = ".;:#?![{=";
   const char *literal_value = NULL;
   char literal_type = '?';
   int type;

   data = *datap;
   len = data_end - data;
   if (len <= 0)
   {
      if (len < 0)
