          * but the sense of the value is inverted */
         *offp = 0;
         *sizep = 0;
         type = DTOVERRIDE_BOOLEAN_INV;
         dtoverlay_debug("  override %s: inverted boolean target %.*s",
                         override_name, name_len, prop_name);
