      else if ((strcmp(override_value, "n") == 0) ||
               (strcmp(override_value, "no") == 0) ||
               (strcmp(override_value, "off") == 0) ||
               (strcmp(override_value, "false") == 0) ||
               (strcmp(override_value, "0") == 0))
         strcpy(override_value, "disabled");
   }

   return type;
